  "reload": {
    "type": "magazine",
    "feed": {
      "empty": 1.83,
      "tactical": 1.83
    },
    "cooldown": {
      "empty": 2.75,
      "tactical": 2.75
    }
  },
  "charging": {
    "semi": {
      // 蓄力模式
      // auto - 按住扳機蓄力，蓄滿後自動發射
      // hold - 按住扳機蓄力，直到鬆開扳機才發射（如果滿足閾值）
      // delay - 按下扳機後自動進行蓄力，蓄滿後自動發射，無法取消
      "type": "auto",
      // 按下/鬆開扳機時每tick蓄力和減少的進度（非負）
      "increase_per_tick": 0.1,
      "decrease_per_tick": 0.1,
      // 開火後削減的蓄力進度
      // 開火模式爲全自動且蓄力模式爲auto時，如果不重置的話第一發完成蓄力後可以按住扳機持續開火
      // 蓄力模式爲hold時，如果開火後蓄力進度仍然大於閾值，即使鬆開扳機也會不受控制的持續開火（如果大於閾值的話不會觸發decrease_per_tick）
      // 蓄力模式爲delay時，此值無效（始終重置爲0）
      "decrease_on_fire": 0.3,
      // 最大蓄力進度
      "max_charge": 0.3,
      // 開火閾值，蓄力至少進度達到此值時允許開火(僅hold模式生效)
      "fire_threshold": 0.3,
      // 在射擊冷卻期間，是否可以進行蓄力
      "charge_during_cooldown": false
    }
  },
  "draw_time": 0.75,
  "put_away_time": 0.65,
  "aim_time": 0.15,
  "sprint_time": 0.1,
  "weight": 1.85,
  "movement_speed": {
    "base": 0.0,
    "aim": -0.15,
    "reload": 0
  },
  "crawl_recoil_multiplier": 0.75,
  "fire_mode": [
    "semi"
  ],
  "allow_attachment_types": [
    "muzzle",
    "laser"
  ],
  "recoil": {
    "pitch": [
      {"time": 0, "value": [1.7, 1.7]},
      {"time": 0.08, "value": [1.8, 1.8]},
      {"time": 0.16, "value": [1.6, 1.6]},
      {"time": 0.35, "value": [-0.125, -0.125]},
      {"time": 0.48, "value": [0.225, 0.225]},
      {"time": 0.7, "value": [0, 0]},
      {"time": 1.0, "value": [0, 0]}
    ],
    "yaw": [
      {"time": 0, "value": [-0.3, 0.05]},
      {"time": 0.08, "value": [-0.7, -0.2]},
      {"time": 0.16, "value": [-0.45, -0.1]},
      {"time": 0.5, "value": [0, 0]}
    ]
  },
  "inaccuracy": {
    "stand": 3.5,
    "move": 5.5,
    "sneak": 2.25,
    "lie": 1.5,
    "aim": 0.1
  }
}

