        {"distance": "infinite", "damage": 6}
      ]
    },
    // 速度 m/s
    "speed": 250,
    // 重力
    "gravity": 0.15,
    // 擊退效果
    "knockback": 0,
    // 阻力
    "friction": 0.02,
    // 點燃目標
    // "ignite": false,
    "ignite": {
      // 點燃實體
      "entity": false,
      // 點燃方塊
      "block": false
    },
    // 點燃時間，默認爲 2 秒，僅用於實體
    "ignite_entity_time": 2,
    // 穿透數
    "pierce": 1
