      // "destroy_block": false
    // }
  },
  // 射擊聲音傳播距離修正
  "fire_sound": {
    // 射擊聲音傳播距離修正乘數
    "fire_multiplier": 1.0,
    // 消音器射擊聲音傳播距離修正乘數
    "silence_multiplier": 1.0
  },
  // 換彈相關
  "reload": {
    // magazine 是彈匣供彈，manual 是手動供彈，fuel 是類燃料罐供彈（消耗一個物品填滿），inventory 是消耗揹包內彈藥供彈（揹包直讀）
    "type": "magazine",
